// Spike: verify shortlist stores against PRD §6 criteria. Read-only, throttled, robots-respecting.
const UA = "beacon-scan/0.1 (+https://github.com/ashishkothari/beacon-scan)";
const RPS_DELAY_MS = 550; // ~1.8 rps, under the 2rps cap
const MERCH_RE = /best|top|trending|featured|popular|new|most-loved|favou?rites?/i;

const hosts = [
  "beminimalist.co",
  "plumgoodness.com",
  "mcaffeine.com",
  "bombayshavingcompany.com",
  "sleepyowl.co",
  "bluetokaicoffee.com",
  "boat-lifestyle.com",
  "thesouledstore.com",
  "snitch.co.in",
  "gymshark.com",
  "allbirds.com",
];

function sleep(ms) { return new Promise(r => setTimeout(r, ms)); }

async function fetchText(url) {
  try {
    const res = await fetch(url, { headers: { "User-Agent": UA }, signal: AbortSignal.timeout(15000) });
    const text = await res.text();
    return { status: res.status, text };
  } catch (e) {
    return { status: 0, text: "", error: String(e) };
  }
}

function parseRobots(text) {
  // very small parser: collect Disallow lines under User-agent: * (or no UA groups at all)
  const lines = text.split(/\r?\n/).map(l => l.trim());
  let inStarGroup = false;
  let anyGroups = false;
  const disallows = [];
  for (const line of lines) {
    if (/^user-agent:/i.test(line)) {
      anyGroups = true;
      const ua = line.split(":")[1].trim();
      inStarGroup = ua === "*";
    } else if (/^disallow:/i.test(line) && inStarGroup) {
      const path = line.split(":").slice(1).join(":").trim();
      if (path) disallows.push(path);
    }
  }
  return { disallows, anyGroups };
}

function isDisallowed(disallows, path) {
  for (const rule of disallows) {
    const pattern = "^" + rule.replace(/[.+^${}()|[\]\\]/g, "\\$&").replace(/\*/g, ".*") + ".*";
    if (new RegExp(pattern).test(path)) return true;
  }
  return false;
}

async function checkHost(host) {
  const result = { host, isShopify: false, notes: [] };
  const base = `https://${host}`;

  const robotsRes = await fetchText(`${base}/robots.txt`);
  await sleep(RPS_DELAY_MS);
  const robots = robotsRes.status === 200 ? parseRobots(robotsRes.text) : { disallows: [], anyGroups: false };
  result.robotsStatus = robotsRes.status;
  if (isDisallowed(robots.disallows, "/products.json")) {
    result.notes.push("robots.txt disallows /products.json for *");
    return result;
  }

  // Page 1 of products.json
  const p1 = await fetchText(`${base}/products.json?limit=250&page=1`);
  await sleep(RPS_DELAY_MS);
  result.productsJsonStatus = p1.status;
  let products = [];
  if (p1.status === 200) {
    try {
      const json = JSON.parse(p1.text);
      if (Array.isArray(json.products)) {
        result.isShopify = true;
        products = json.products;
      }
    } catch (e) {
      result.notes.push("products.json not valid JSON");
    }
  }
  if (!result.isShopify) {
    result.notes.push(`products.json not usable (status ${p1.status})`);
    return result;
  }

  // page through, cap 800
  let page = 2;
  while (products.length < 800) {
    const pn = await fetchText(`${base}/products.json?limit=250&page=${page}`);
    await sleep(RPS_DELAY_MS);
    if (pn.status !== 200) break;
    try {
      const json = JSON.parse(pn.text);
      if (!Array.isArray(json.products) || json.products.length === 0) break;
      products = products.concat(json.products);
      if (json.products.length < 250) break;
    } catch (e) { break; }
    page++;
    if (page > 4) break; // cap ~ 1000 but we truncate to 800 below anyway
  }
  products = products.slice(0, 800);

  let totalVariants = 0, soldOutVariants = 0, multiOptionProducts = 0;
  let soldOutProductHandle = null;
  for (const p of products) {
    const variants = p.variants || [];
    totalVariants += variants.length;
    const hasSoldOut = variants.some(v => v.available === false);
    if (hasSoldOut && !soldOutProductHandle) soldOutProductHandle = p.handle;
    soldOutVariants += variants.filter(v => v.available === false).length;
    if ((p.options || []).length >= 2) multiOptionProducts++;
  }
  result.productCount = products.length;
  result.totalVariants = totalVariants;
  result.soldOutVariants = soldOutVariants;
  result.soldOutVariantPct = totalVariants ? +(100 * soldOutVariants / totalVariants).toFixed(1) : 0;
  result.multiOptionPct = products.length ? +(100 * multiOptionProducts / products.length).toFixed(1) : 0;

  // collections.json
  if (!isDisallowed(robots.disallows, "/collections.json")) {
    const c1 = await fetchText(`${base}/collections.json?limit=250`);
    await sleep(RPS_DELAY_MS);
    result.collectionsJsonStatus = c1.status;
    if (c1.status === 200) {
      try {
        const json = JSON.parse(c1.text);
        const collections = Array.isArray(json.collections) ? json.collections : [];
        result.collectionCount = collections.length;
        const merch = collections.filter(c => MERCH_RE.test(c.handle) || MERCH_RE.test(c.title || ""))
          .filter(c => !["all", "frontpage"].includes(c.handle));
        result.hasMerchCollection = merch.length > 0;
        result.merchCollectionHandles = merch.map(c => c.handle).slice(0, 5);
      } catch (e) {
        result.notes.push("collections.json not valid JSON");
      }
    }
  } else {
    result.notes.push("robots.txt disallows /collections.json for *");
  }

  // one PDP of a sold-out product
  if (soldOutProductHandle) {
    const pdpPath = `/products/${soldOutProductHandle}`;
    if (!isDisallowed(robots.disallows, pdpPath)) {
      const pdp = await fetchText(`${base}${pdpPath}`);
      await sleep(RPS_DELAY_MS);
      result.pdpStatus = pdp.status;
      result.pdpHandle = soldOutProductHandle;
      result.hasSwymInPdp = pdp.status === 200 && /swym/i.test(pdp.text);
    } else {
      result.notes.push("robots.txt disallows the sample PDP path");
    }
  } else {
    result.notes.push("no sold-out product found in first 800 to sample a PDP");
  }

  return result;
}

const results = [];
for (const host of hosts) {
  process.stderr.write(`checking ${host}...\n`);
  const r = await checkHost(host);
  results.push(r);
  process.stderr.write(`  -> ${JSON.stringify(r)}\n`);
}

console.log(JSON.stringify(results, null, 2));

