// Follow-up spike: refined size-option metric + multi-PDP swym check for top candidates.
const UA = "beacon-scan/0.1 (+https://github.com/ashishkothari/beacon-scan)";
const DELAY = 550;
const SIZE_RE = /size|sz|waist/i;
const KNOWN_SIZES = new Set(["XXS","XS","S","M","L","XL","XXL","XXXL","2XL","3XL","4XL","5XL"]);

function sleep(ms) { return new Promise(r => setTimeout(r, ms)); }
async function fetchText(url) {
  try {
    const res = await fetch(url, { headers: { "User-Agent": UA }, signal: AbortSignal.timeout(15000) });
    const text = await res.text();
    return { status: res.status, text };
  } catch (e) { return { status: 0, text: "", error: String(e) }; }
}

function isSizeOption(opt) {
  if (SIZE_RE.test(opt.name)) return true;
  const vals = opt.values.map(v => v.toUpperCase());
  const knownHits = vals.filter(v => KNOWN_SIZES.has(v) || /^\d{2}$/.test(v)).length;
  return knownHits >= Math.max(2, Math.ceil(vals.length * 0.5));
}

const hosts = ["bombayshavingcompany.com", "bluetokaicoffee.com", "boat-lifestyle.com", "gymshark.com", "allbirds.com", "sleepyowl.co"];

const out = [];
for (const host of hosts) {
  process.stderr.write(`\n== ${host} ==\n`);
  let products = [];
  for (let page = 1; page <= 4; page++) {
    const r = await fetchText(`https://${host}/products.json?limit=250&page=${page}`);
    await sleep(DELAY);
    if (r.status !== 200) break;
    try {
      const j = JSON.parse(r.text);
      if (!Array.isArray(j.products) || j.products.length === 0) break;
      products = products.concat(j.products);
      if (j.products.length < 250) break;
    } catch { break; }
  }
  products = products.slice(0, 800);
  let withSizeOption = 0, withAnySoldOut = 0;
  const soldOutHandles = [];
  for (const p of products) {
    const opts = p.options || [];
    if (opts.some(isSizeOption)) withSizeOption++;
    const variants = p.variants || [];
    if (variants.some(v => v.available === false)) {
      withAnySoldOut++;
      if (soldOutHandles.length < 5) soldOutHandles.push(p.handle);
    }
  }
  const pct = products.length ? +(100 * withSizeOption / products.length).toFixed(1) : 0;
  process.stderr.write(`products=${products.length} withSizeOptionPct=${pct} soldOutProducts=${withAnySoldOut}\n`);

  // check swym / bis markers on up to 3 sold-out PDPs
  const pdpChecks = [];
  for (const handle of soldOutHandles.slice(0, 3)) {
    const pdp = await fetchText(`https://${host}/products/${handle}`);
    await sleep(DELAY);
    const hasSwym = /swym/i.test(pdp.text);
    const hasBis = /back in stock|notify me|klaviyo-bis|\bbis\b/i.test(pdp.text);
    pdpChecks.push({ handle, status: pdp.status, hasSwym, hasBis });
    process.stderr.write(`  pdp ${handle}: status=${pdp.status} swym=${hasSwym} bis=${hasBis}\n`);
  }

  out.push({ host, productCount: products.length, withSizeOptionPct: pct, soldOutProducts: withAnySoldOut, pdpChecks });
}
console.log(JSON.stringify(out, null, 2));

