// Records real, throttled, robots-respecting fixtures for the chosen store into tests/fixtures/<host>/.
import { mkdir, writeFile } from "node:fs/promises";
import path from "node:path";

const HOST = "bluetokaicoffee.com";
const UA = "beacon-scan/0.1 (+https://github.com/ashishkothari/beacon-scan)";
const DELAY = 550;
const OUT = path.join("/Users/ashishkothari/Documents/beacon-takehome/tests/fixtures", HOST);
const MERCH_RE = /best|top|trending|featured|popular|new|most-loved|favou?rites?/i;

function sleep(ms) { return new Promise((r) => setTimeout(r, ms)); }

async function get(pathname) {
  const res = await fetch(`https://${HOST}${pathname}`, {
    headers: { "User-Agent": UA },
    signal: AbortSignal.timeout(20000),
  });
  const text = await res.text();
  await sleep(DELAY);
  return { status: res.status, text };
}

async function saveText(name, text) {
  await writeFile(path.join(OUT, name), text, "utf8");
  console.error(`wrote ${name} (${text.length} bytes)`);
}

async function saveJsonPretty(name, obj) {
  await saveText(name, JSON.stringify(obj, null, 2));
}

async function main() {
  await mkdir(OUT, { recursive: true });

  // robots.txt
  const robots = await get("/robots.txt");
  await saveText("robots.txt", robots.text);

  // homepage
  const home = await get("/");
  await saveText("home.html", home.text);

  // products, paged
  const p1 = await get("/products.json?limit=250&page=1");
  const p1json = JSON.parse(p1.text);
  await saveJsonPretty("products.page1.json", p1json);
  console.error(`page1 products: ${p1json.products.length}`);

  const p2 = await get("/products.json?limit=250&page=2");
  const p2json = JSON.parse(p2.text);
  await saveJsonPretty("products.page2.json", p2json);
  console.error(`page2 products: ${p2json.products.length}`);

  // collections (full, real)
  const c1 = await get("/collections.json?limit=250");
  const c1json = JSON.parse(c1.text);
  await saveJsonPretty("collections.json", c1json);
  console.error(`collections: ${c1json.collections.length}`);

  // pick a bounded subset: all merch collections + top 15 by productsCount, cap 20 total
  const collections = c1json.collections;
  const merch = collections.filter(
    (c) => (MERCH_RE.test(c.handle) || MERCH_RE.test(c.title || "")) && !["all", "frontpage"].includes(c.handle),
  );
  const merchHandles = new Set(merch.map((c) => c.handle));
  const rest = collections
    .filter((c) => !merchHandles.has(c.handle))
    .sort((a, b) => (b.products_count || 0) - (a.products_count || 0))
    .slice(0, Math.max(0, 20 - merch.length));
  const chosen = [...merch, ...rest].slice(0, 20);
  console.error(`recording ${chosen.length} collection product listings: ${chosen.map((c) => c.handle).join(", ")}`);

  const allProducts = p1json.products.concat(p2json.products);
  const soldOutHandles = [];
  for (const cSpec of chosen) {
    const cRes = await get(`/collections/${cSpec.handle}/products.json?limit=250`);
    let cJson;
    try {
      cJson = JSON.parse(cRes.text);
    } catch (e) {
      console.error(`  ! ${cSpec.handle}: not JSON (status ${cRes.status}), skipping`);
      continue;
    }
    await saveJsonPretty(`collection.${cSpec.handle}.json`, cJson);
    console.error(`  ${cSpec.handle}: ${cJson.products?.length ?? 0} products`);
  }

  // find sold-out product handles (highest leakage first) for PDP sampling
  const withLeakage = allProducts
    .map((p) => {
      const variants = p.variants || [];
      const soldOut = variants.filter((v) => v.available === false).length;
      return { handle: p.handle, soldOut, total: variants.length, leakage: variants.length ? soldOut / variants.length : 0 };
    })
    .filter((p) => p.soldOut > 0)
    .sort((a, b) => b.leakage - a.leakage);

  const pdpHandles = withLeakage.slice(0, 3).map((p) => p.handle);
  console.error(`PDP sample: ${pdpHandles.join(", ")}`);
  for (const handle of pdpHandles) {
    const pdp = await get(`/products/${handle}`);
    await saveText(`pdp.${handle}.html`, pdp.text);
  }

  console.error("done");
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});

