7	import type { AvailabilityDelta, BeaconConfig, Findings, PdpMarkers, RestockRow, StoreSnapshot } from "../types.js";
8	import { mergeConfig } from "./default-config.js";
9	import { computeRestockRow, rankRestockRows } from "./restock.js";
10	import { buildScorecard } from "./scorecard.js";
11	import { percentile } from "./stats.js";
12	
13	const ASSUMPTIONS = [
14	  "A1: public storefront JSON reflects live availability; can lag minutes behind actual stock",
15	  "A2: collection order approximates merchandising intent; bestseller-style handles approximate demand",
16	  "A3: a sold-out variant on a merchandised product is intent lost; we cannot see how much",
17	  "A4: detection of back-in-stock capture by HTML markers is approximate (themes vary)",
18	  "A5: assumes the reviewer runs on macOS/Linux with Node >=20",
19	];
20	
21	export function analyse(
22	  snapshot: StoreSnapshot,
23	  markers: PdpMarkers,
24	  config?: Partial<BeaconConfig>,
25	  delta?: AvailabilityDelta,
26	  now: () => Date = () => new Date(),
27	): Findings {
28	  const cfg = mergeConfig(config);
29	  const nowDate = now();
30	
31	  const catalogP90Price = percentile(
32	    snapshot.products.flatMap((p) => p.variants.map((v) => v.price)),
33	    0.9,
34	  );
35	  const collectionsByHandle = new Map(snapshot.collections.map((c) => [c.handle, c]));
36	
37	  const restockRows: RestockRow[] = [];
38	  for (const product of snapshot.products) {
39	    const row = computeRestockRow(product, collectionsByHandle, cfg, catalogP90Price, nowDate, delta);
40	    if (row) restockRows.push(row);
41	  }
42	  const restock = rankRestockRows(restockRows);
43	
44	  const scorecard = buildScorecard(snapshot, markers, cfg);
45	
46	  const variantsTotal = snapshot.products.reduce((sum, p) => sum + p.variants.length, 0);
47	  const variantsSoldOut = snapshot.products.reduce(
48	    (sum, p) => sum + p.variants.filter((v) => !v.available).length,
49	    0,
