6	import type { AvailabilityDelta, StoreSnapshot } from "../types.js";
7	
8	export function diff(a: StoreSnapshot, b: StoreSnapshot): AvailabilityDelta {
9	  const aByHandle = new Map(a.products.map((p) => [p.handle, p]));
10	  const bByHandle = new Map(b.products.map((p) => [p.handle, p]));
11	
12	  const soldThrough: { handle: string; variantTitle: string }[] = [];
13	  const restocked: { handle: string; variantTitle: string }[] = [];
14	
15	  for (const bProduct of b.products) {
16	    const aProduct = aByHandle.get(bProduct.handle);
17	    if (!aProduct) continue;
18	    const aVariantsById = new Map(aProduct.variants.map((v) => [v.id, v]));
19	    for (const bVariant of bProduct.variants) {
20	      const aVariant = aVariantsById.get(bVariant.id);
21	      if (!aVariant) continue;
22	      if (aVariant.available && !bVariant.available) {
23	        soldThrough.push({ handle: bProduct.handle, variantTitle: bVariant.title });
24	      } else if (!aVariant.available && bVariant.available) {
25	        restocked.push({ handle: bProduct.handle, variantTitle: bVariant.title });
26	      }
27	    }
28	  }
29	
30	  const newProducts = b.products.filter((p) => !aByHandle.has(p.handle)).map((p) => p.handle);
31	  const removedProducts = a.products.filter((p) => !bByHandle.has(p.handle)).map((p) => p.handle);
32	
33	  return {
34	    fromFetchedAt: a.fetchedAt,
35	    toFetchedAt: b.fetchedAt,
36	    soldThrough,
37	    restocked,
38	    newProducts,
39	    removedProducts,
40	  };
41	}

