15	/**
16	 * Domain Context: Swym's own markers plus the generic back-in-stock capture vocabulary.
17	 * Checked longest/most-specific first so an occurrence of `swym-button` is reported as
18	 * exactly that — not also as a separate bare `swym` hit — matching the spec's "Store
19	 * using Swym" scenario (`markers: ["swym-button"]`, not `["swym-button", "swym"]`).
20	 */
21	const MARKER_CHECKS: Array<{ id: string; test: (html: string) => boolean }> = [
22	  { id: "swym-notify", test: (h) => /swym-notify/i.test(h) },
23	  { id: "swym-button", test: (h) => /swym-button/i.test(h) },
24	  // Bare "swym" only counts when it's not part of a more specific swym-* token already
25	  // matched above (negative lookahead for a trailing hyphen).
26	  { id: "swym", test: (h) => /swym(?!-)/i.test(h) },
27	  { id: "klaviyo-bis", test: (h) => /klaviyo-bis/i.test(h) },
28	  { id: "back in stock", test: (h) => /back in stock/i.test(h) },
29	  { id: "notify me", test: (h) => /notify me/i.test(h) },
30	  { id: "restock", test: (h) => /restock/i.test(h) },
31	  // "bis" alone is ambiguous (substrings of unrelated words) — require word boundaries
32	  // and exclude the "-bis" inside "klaviyo-bis" (already counted above).
33	  { id: "bis", test: (h) => /(?<!-)\bbis\b(?!-)/i.test(h) },
34	];
35	
36	export function detectPdpMarkers(html: string): {
37	  hasBisCapture: boolean;
38	  hasSwym: boolean;
39	  markers: string[];
40	} {
41	  const markers = MARKER_CHECKS.filter((m) => m.test(html)).map((m) => m.id);
42	  return {
43	    hasBisCapture: markers.length > 0,
44	    hasSwym: markers.some((m) => m.startsWith("swym")),
45	    markers,
46	  };
47	}
