49	/** Requirement "PDP marker sampling": products with ≥1 sold-out variant, highest
50	 * leakage (soldOut/total) first; ties broken by absolute sold-out count then handle for
51	 * determinism. */
52	export function selectPdpSampleCandidates(products: Product[], limit: number): Product[] {
53	  const withLeakage = products
54	    .map((p) => {
55	      const soldOut = p.variants.filter((v) => !v.available).length;
56	      const total = p.variants.length;
57	      return { product: p, soldOut, total, leakage: total > 0 ? soldOut / total : 0 };
58	    })
59	    .filter((x) => x.soldOut > 0);
60	  withLeakage.sort(
61	    (a, b) => b.leakage - a.leakage || b.soldOut - a.soldOut || a.product.handle.localeCompare(b.product.handle),
62	  );
63	  return withLeakage.slice(0, Math.max(0, limit)).map((x) => x.product);
64	}
