78	  const limit = opts.pdpSample ?? defaultConfig.limits.pdpSample;
79	  const candidates = selectPdpSampleCandidates(snapshot.products, limit);
80	  const sampled: PdpMarkers["sampled"] = [];
81	
82	  if (opts.offlineFixturesDir) {
83	    for (const product of candidates) {
84	      const file = path.join(opts.offlineFixturesDir, `pdp.${product.handle}.html`);
85	      let html: string;
