90	        continue;
91	      }
92	      const markers = detectPdpMarkers(html);
93	      sampled.push({ handle: product.handle, url: product.url, ...markers });
94	      opts.onProgress?.("pdp sample", `${sampled.length}/${Math.min(limit, candidates.length)}`);
95	    }
96	    return { sampled };
97	  }
98	
99	  const http = createHttp(defaultConfig, {
100	    cacheDir: opts.cacheDir,
101	    noCache: opts.noCache,
102	    onProgress: opts.onProgress,
103	  });
104	  for (const product of candidates) {
105	    const res = await http.get(product.url);
106	    const markers = detectPdpMarkers(res.body);
107	    sampled.push({ handle: product.handle, url: product.url, ...markers });
108	    opts.onProgress?.("pdp sample", `${sampled.length}/${candidates.length}`);
109	  }
110	  return { sampled };
111	}

