test: {
  environment: "node",
  include: ["tests/**/*.test.ts"],
  passWithNoTests: true,
  // A couple of collector tests exercise real setTimeout/AbortController timing
  // (http.ts's backoff delay isn't clock-injectable by design — see the "Burst of
  // 429s" test). Vitest's 5s default test timeout is fine on an idle machine but
  // has been observed to trip under real system load (multiple test files' worker
  // threads plus other concurrent processes competing for the event loop), causing
  // spurious AbortController fires and doubled retry counts on otherwise-correct
  // mocked-fetch tests. A generous global timeout removes that flakiness without
  // slowing down a normal run (tests still complete in well under a second each).
  testTimeout: 20000,
},

